def _line(x, y):
    xc = x - x.mean()
    gain = xc @ (y - y.mean()) / (xc @ xc)
    return (gain, y.mean() - gain * x.mean())

def _fit(dt, time, past, hold, x, yc, yr):
    from scipy.optimize import least_squares
    ic, ir = (np.isfinite(yc), np.isfinite(yr))
    target = np.r_[yc[ic], yr[ir]]
    n_curve = ic.sum()
    bounds = (np.log(0.025), np.log(100.0))

    def design(u):
        c, r = _design(np.exp(u), dt, time, past, hold, x)
        return np.vstack((c[ic], r[ir]))

    def profile(u, scale, robust):
        a = design(u) / scale[:, None]
        y = target / scale
        w = np.linalg.lstsq(a, y, rcond=None)[0]
        if robust:
            for _ in range(14):
                e = np.einsum('ij,j->i', a, w) - y
                q = (1.0 + (e / 2.5) ** 2) ** (-0.5)
                w = np.linalg.lstsq(a * q[:, None], y * q, rcond=None)[0]
        e = np.einsum('ij,j->i', a, w) - y
        if robust:
            e = 2.5 * np.sign(e) * np.sqrt(np.log1p((e / 2.5) ** 2))
        return (e, w)
    scale = np.ones(len(target))
    pilot = min((least_squares(lambda u: profile(u, scale, False)[0], np.log(start), bounds=bounds) for start in ((0.35, 2.5), (0.8, 5.0))), key=lambda fit: fit.cost)
    residual = profile(pilot.x, scale, False)[0]
    for sl in (slice(None, n_curve), slice(n_curve, None)):
        e = residual[sl]
        if len(e):
            scale[sl] = max(1.4826 * np.median(np.abs(e - np.median(e))), 1e-07)
    fit = least_squares(lambda u: profile(u, scale, True)[0], pilot.x, bounds=bounds)
    return (np.exp(fit.x), profile(fit.x, scale, True)[1])

def _clean_calibration(cmd, true):
    if len(cmd) < 3:
        return np.ones(len(cmd), dtype=bool)
    i, j = np.triu_indices(len(cmd), 1)
    dx = cmd[j] - cmd[i]
    valid = dx != 0
    if not np.any(valid):
        return np.ones(len(cmd), dtype=bool)
    slopes = (true[j[valid]] - true[i[valid]]) / dx[valid]
    offsets = true[:, None] - cmd[:, None] * slopes
    deviations = np.abs(offsets - np.median(offsets, axis=0))
    return deviations[:, np.argmin(np.median(deviations, axis=0))] <= 3.0
